sp_widget.client_script:
api.controller = function($scope, $timeout, spModal) {

  /* =========================================================
     GATENOW · MY AWARDS · Client script

     Tabs, search and paging run against the list already in
     memory. The only server calls are accept and decline, which
     are real writes and reload the list afterwards so the row
     shows its new state rather than sitting stale.
     ========================================================= */

  var c = this;

  c.query = '';
  c.page  = 1;
  c.busy  = '';

  var PER_PAGE = c.data.pageSize || 10;

  /* Waiting on you leads, because it is the only tab with
     anything to do on it. */
  c.tabs = [
    { key: 'pending',  label: c.data.t.tabPending },
    { key: 'active',   label: c.data.t.tabActive },
    { key: 'done',     label: c.data.t.tabDone },
    { key: 'declined', label: c.data.t.tabDeclined },
    { key: 'all',      label: c.data.t.tabAll }
  ];

  /* land on whichever tab has something on it */
  c.tab = (c.data.counts && c.data.counts.pending > 0) ? 'pending' : 'all';

  function hit(a, q) {
    return (
      (a.program  || '').toLowerCase().indexOf(q) !== -1 ||
      (a.number   || '').toLowerCase().indexOf(q) !== -1 ||
      (a.title    || '').toLowerCase().indexOf(q) !== -1 ||
      (a.category || '').toLowerCase().indexOf(q) !== -1
    );
  }

  function matching() {
    var q = (c.query || '').trim().toLowerCase();

    var out = (c.data.awards || []).filter(function(a) {
      if (c.tab !== 'all' && a.state !== c.tab) return false;
      if (q && !hit(a, q)) return false;
      return true;
    });

    /* anything waiting on a decision sorts to the top whichever
       tab is open, because it is the only thing here that has a
       cost attached to ignoring it */
    out.sort(function(x, y) {
      if (x.state === 'pending' && y.state !== 'pending') return -1;
      if (y.state === 'pending' && x.state !== 'pending') return 1;
      return 0;
    });

    return out;
  }

  c.total     = function() { return matching().length; };
  c.pageCount = function() { return Math.max(1, Math.ceil(matching().length / PER_PAGE)); };

  c.shown = function() {
    var start = (c.page - 1) * PER_PAGE;
    return matching().slice(start, start + PER_PAGE);
  };

  c.rangeFrom = function() {
    return matching().length === 0 ? 0 : ((c.page - 1) * PER_PAGE) + 1;
  };

  c.rangeTo = function() {
    return Math.min(c.page * PER_PAGE, matching().length);
  };

  function reset() { c.page = 1; }

  c.onChange = function() { reset(); };

  c.setTab = function(key) {
    if (c.tab === key) return;
    c.tab = key;
    reset();
  };

  c.clearSearch = function() { c.query = ''; reset(); };

  c.clearAll = function() {
    c.query = '';
    c.tab = 'all';
    reset();
  };


  /* =====================================================
     PAGING
     ===================================================== */

  c.goto = function(n) {
    if (n === '...') return;
    if (n < 1 || n > c.pageCount() || n === c.page) return;
    c.page = n;
  };

  c.prev = function() { c.goto(c.page - 1); };
  c.next = function() { c.goto(c.page + 1); };

  c.pages = function() {
    var n = c.pageCount();
    var p = c.page;
    var out = [];

    if (n <= 7) {
      for (var i = 1; i <= n; i++) out.push(i);
      return out;
    }

    out.push(1);

    var from = Math.max(2, p - 1);
    var to   = Math.min(n - 1, p + 1);

    if (p <= 3) to = 4;
    if (p >= n - 2) from = n - 3;

    if (from > 2) out.push('...');
    for (var j = from; j <= to; j++) out.push(j);
    if (to < n - 1) out.push('...');

    out.push(n);
    return out;
  };


  /* =====================================================
     DECISIONS

     Both are confirmed first. Accepting commits to a reporting
     schedule and declining cannot be undone, so neither should
     be one careless click away.
     ===================================================== */

  function tell(title, message) {
    spModal.open({
      title: title,
      message: message,
      buttons: [{ label: c.data.t.ok, primary: true }]
    });
  }

  function send(award, action, okMessage) {
    c.busy = award.sysId;

    c.server.get({ action: action, sys_id: award.sysId }).then(function(r) {
      c.busy = '';
      var resp = (r && r.data) ? r.data : {};

      if (resp.success) {
        tell(okMessage, award.program);
        /* the reload brings back the new state and the recounted
           tiles in one pass */
        c.server.update();
      } else {
        tell(c.data.t.failed, resp.error || '');
      }
    }, function() {
      c.busy = '';
      tell(c.data.t.failed, '');
    });
  }

  c.accept = function(award) {
    if (!award || !award.canAct || c.busy) return;

    spModal.open({
      title: c.data.t.acceptTitle,
      message: c.data.t.acceptText,
      buttons: [
        { label: c.data.t.keep, cancel: true },
        { label: c.data.t.acceptYes, primary: true }
      ]
    }).then(function() {
      send(award, 'acknowledge', c.data.t.accepted);
    });
  };

  c.decline = function(award) {
    if (!award || !award.canAct || c.busy) return;

    spModal.open({
      title: c.data.t.declineTitle,
      message: c.data.t.declineText,
      buttons: [
        { label: c.data.t.keep, cancel: true },
        { label: c.data.t.declineYes, primary: true }
      ]
    }).then(function() {
      send(award, 'decline', c.data.t.declined);
    });
  };

}

sp_widget.css:
/* =========================================================
   GATENOW · MY AWARDS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Same tokens as the dashboard and the funding programs page:
   the navy, the one accent blue, neutrals built from the navy
   at different opacities, and the same type scale.

   ONE ADDITION
   A red, used in exactly one place. Declining an award cannot
   be undone, and a decline that looks like every other button
   is a decline someone makes by accident.

   TYPE
     tile      30  700  tabular   headline figures
     title     26  700  -0.03em   page title
     program   19  600  -0.018em  award heading
     figure    24  700  tabular   the amount
     body      15  400             supporting copy
     data      14  600  tabular    dates
     label     11  600   0.14em    uppercase small caps
   ========================================================= */

/* ---------- overflow overrides ----------
   Service Portal wraps every widget in a panel that clips
   anything leaving its box, which cuts off the sidebar tooltips.
   Same block as the dashboard, so the two behave identically.
   ------------------------------------------------------- */

.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout { overflow: visible !important; }

/* The column holds the rail and lets it decide how wide to be.
   It used to carry a width through an inline ng-style, which is
   what put 140px of the rail on top of this page: the column
   reserved 96 while the rail draws 236.

   The transition moved to the rail, which is the element that
   actually changes width. Animating a wrapper that never
   resized was doing nothing. */

.aw-sidebar {
  flex: 0 0 auto;
  overflow: visible;
}


/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$a-navy:   #0a2540;
$a-ink-2:  rgba(10, 37, 64, 0.72);
$a-ink-3:  rgba(10, 37, 64, 0.54);
$a-ink-4:  rgba(10, 37, 64, 0.38);
$a-line:   rgba(10, 37, 64, 0.10);
$a-line-2: rgba(10, 37, 64, 0.06);
$a-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$a-blue:    #1560e0;
$a-blue-dk: #0f4cbb;
$a-blue-1:  rgba(21, 96, 224, 0.08);
$a-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- state ---------- */
$a-soon:   #0d7d8c;
$a-good:   #1f8a63;
$a-good-1: rgba(31, 138, 99, 0.10);
$a-warn:   #a4741f;
$a-warn-1: rgba(164, 116, 31, 0.10);
$a-warn-2: rgba(164, 116, 31, 0.26);

/* the one destructive colour, used only on decline */
$a-stop:   #b8394a;
$a-stop-1: rgba(184, 57, 74, 0.08);
$a-stop-2: rgba(184, 57, 74, 0.28);

$a-white: #ffffff;
$a-page:  #f4f6fb;
$a-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$a-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gn-layout {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: $a-page;
  font-family: $a-font;
}

/* Without min-width: 0 a flex child refuses to shrink below its
   own content width, and slides under the rail rather than
   narrowing. That is the usual cause of a stubborn overlap once
   the widths are right. */
.gaw {
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.gaw {
  min-height: 100vh;
  padding: 30px 38px 72px;
  background: $a-page;
  font-family: $a-font;
  color: $a-navy;
  -webkit-font-smoothing: antialiased;
}

.gaw *,
.gaw *::before,
.gaw *::after { box-sizing: border-box; }


/* =========================================================
   HEADER
   ========================================================= */

.gaw-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  margin-bottom: 26px;
}

.gaw .gaw-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $a-navy;
}

.gaw-top__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.gaw-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 320px;
  height: 42px;
  padding: 0 12px 0 14px;
  margin: 0;
  border: 1px solid $a-line;
  border-radius: 11px;
  background: $a-white;
  font-weight: 400;
  transition: border-color 0.4s $a-ease, box-shadow 0.4s $a-ease;
}

.gaw-search:focus-within {
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $a-blue-1;
}

.gaw-search__icon {
  font-size: 13px;
  color: $a-ink-4;
  flex-shrink: 0;
}

.gaw-search__field {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: $a-navy;
}

.gaw-search__field::placeholder { color: $a-ink-4; }

.gaw-search__clear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: $a-tint;
  color: $a-ink-3;
  font-size: 10px;
  cursor: pointer;
  flex-shrink: 0;
}

.gaw-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background:#1560e0;
  color: $a-white;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
  flex-shrink: 0;
}


/* =========================================================
   NOTHING YET
   ========================================================= */

.gaw-blank {
  max-width: 520px;
  margin: 70px auto;
  padding: 52px 34px 46px;
  border: 1px solid $a-line;
  border-radius: 18px;
  background: $a-white;
  text-align: center;
}

.gaw-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: $a-blue-1;
  color: $a-blue;
  font-size: 22px;
}

.gaw .gaw-blank__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $a-navy;
}

.gaw .gaw-blank__text {
  max-width: 44ch;
  margin: 11px auto 24px;
  font-size: 15px;
  line-height: 1.64;
  color: $a-ink-3;
}


/* =========================================================
   TILES
   ========================================================= */

.gaw-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.gaw-tile {
  position: relative;
  padding: 20px 22px 22px;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: transform 0.5s $a-ease, box-shadow 0.5s $a-ease;
}

.gaw-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(10, 37, 64, 0.08);
}

.gaw-tile__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: $a-blue-2;
  transform-origin: left center;
}

.gaw-tile.is-alert .gaw-tile__rule { background: $a-warn-2; }

.gaw .gaw-tile__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw .gaw-tile__value {
  margin: 12px 0 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.034em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gaw .gaw-tile__note {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: $a-ink-3;
}

.gaw-tile.is-alert .gaw-tile__note {
  color: $a-warn;
  font-weight: 500;
}


/* =========================================================
   TABS
   ========================================================= */

.gaw-filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 20px;
  padding-bottom: 16px;
  margin-bottom: 16px;
  border-bottom: 1px solid $a-line;
}

.gaw-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.gaw-tab {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: $a-ink-2;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gaw-tab:hover {
  background: rgba(255, 255, 255, 0.7);
  color: $a-navy;
}

.gaw-tab.is-on {
  background: $a-white;
  border-color: $a-line;
  color: $a-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.05);
}

.gaw-tab__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $a-ink-4;
  flex-shrink: 0;
}

/* only the tab with something to do carries the accent */
.gaw-tab__dot--pending  { background: $a-warn; }
.gaw-tab__dot--active   { background: $a-blue; }
.gaw-tab__dot--done     { background: $a-good; }
.gaw-tab__dot--declined { background: $a-ink-4; }

.gaw-tab__count {
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}

.gaw .gaw-range {
  margin: 0;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}


/* =========================================================
   AWARD CARD
   ========================================================= */

.gaw-list {
  display: grid;
  gap: 14px;
}

.gaw-card {
  position: relative;
  padding: 22px 26px 20px 28px;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: border-color 0.5s $a-ease, box-shadow 0.5s $a-ease;
}

.gaw-card:hover {
  border-color: $a-blue-2;
  box-shadow: 0 14px 34px rgba(10, 37, 64, 0.08);
}

/* the rail states where the award stands without another badge */
.gaw-card__rail {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
}

.gaw-card--pending .gaw-card__rail  { background: $a-warn; }
.gaw-card--active .gaw-card__rail   { background: $a-blue; }
.gaw-card--done .gaw-card__rail     { background: $a-good; }
.gaw-card--declined .gaw-card__rail { background: rgba(10, 37, 64, 0.16); }

/* an award waiting on a decision is the only thing here with a
   cost attached to ignoring it, so it is the only one tinted */
.gaw-card--pending { background: linear-gradient(180deg, rgba(164, 116, 31, 0.04) 0%, $a-white 42%); }

.gaw-card__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 26px;
  align-items: start;
  padding-bottom: 18px;
  margin-bottom: 16px;
  border-bottom: 1px solid $a-line-2;
}

.gaw-card__lead { min-width: 0; }

.gaw-card__top {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 10px;
}

.gaw-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.gaw-state__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gaw-state--pending  { color: $a-warn; }
.gaw-state--active   { color: $a-blue-dk; }
.gaw-state--done     { color: $a-good; }
.gaw-state--declined { color: $a-ink-4; }

.gaw-state--pending .gaw-state__dot  { background: $a-warn; }
.gaw-state--active .gaw-state__dot   { background: $a-blue; }
.gaw-state--done .gaw-state__dot     { background: $a-good; }
.gaw-state--declined .gaw-state__dot {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.28);
}

.gaw-card__meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw-card__sep { color: rgba(10, 37, 64, 0.22); }

.gaw-wait {
  padding: 3px 9px;
  border: 1px solid $a-warn-2;
  border-radius: 6px;
  background: $a-warn-1;
  color: $a-warn;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.gaw .gaw-card__program {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.018em;
  color: $a-navy;
}

.gaw .gaw-card__title {
  max-width: 68ch;
  margin: 6px 0 0;
  font-size: 15px;
  line-height: 1.55;
  color: $a-ink-2;
}

.gaw .gaw-card__hint {
  margin: 8px 0 0;
  font-size: 13.5px;
  color: $a-ink-4;
}

.gaw-card--declined .gaw-card__program { color: $a-ink-3; }


/* ---------- the amount ---------- */

.gaw-card__figure {
  text-align: right;
  min-width: 0;
}

.gaw-figure__label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw-figure__value {
  display: block;
  margin-top: 8px;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

/* said plainly rather than left to be assumed, because a
   requested figure is not an awarded one */
.gaw-figure__note {
  display: block;
  margin-top: 7px;
  font-size: 11.5px;
  line-height: 1.5;
  color: $a-ink-4;
}


/* ---------- foot ---------- */

.gaw-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
}

.gaw .gaw-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 30px;
  margin: 0;
  padding: 0;
}

.gaw-fact {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.gaw .gaw-fact dt {
  margin: 0;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gaw .gaw-fact dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gaw-acts {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.gaw-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 17px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gaw-btn--primary {
  background: $a-blue;
  border-color: $a-blue;
  color: $a-white;
}

.gaw-btn--primary:hover,
.gaw-btn--primary:focus {
  background: $a-blue-dk;
  border-color: $a-blue-dk;
  color: $a-white;
  text-decoration: none;
}

/* Declining cannot be undone, so it does not look like every
   other button on the page. It is not filled either, because a
   solid red next to a solid blue is a coin toss at speed. */
.gaw-btn--danger {
  border-color: $a-stop-2;
  color: $a-stop;
}

.gaw-btn--danger:hover,
.gaw-btn--danger:focus {
  background: $a-stop-1;
  border-color: $a-stop;
  color: $a-stop;
  text-decoration: none;
}

.gaw-btn--ghost {
  border-color: $a-line;
  color: $a-ink-2;
}

.gaw-btn--ghost:hover,
.gaw-btn--ghost:focus {
  border-color: $a-blue-2;
  color: $a-blue-dk;
  text-decoration: none;
}

.gaw-btn--quiet { color: $a-ink-3; }

.gaw-btn--quiet:hover,
.gaw-btn--quiet:focus {
  color: $a-navy;
  text-decoration: none;
}

.gaw-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.gaw-btn:focus-visible,
.gaw-tab:focus-visible,
.gaw-search__clear:focus-visible {
  outline: 2px solid $a-blue;
  outline-offset: 2px;
}


/* =========================================================
   NO MATCH AND PAGER
   ========================================================= */

.gaw-nomatch {
  padding: 62px 24px;
  border: 1px dashed $a-line;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.6);
  text-align: center;
}

.gaw .gaw-nomatch__title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $a-navy;
}

.gaw .gaw-nomatch__text {
  max-width: 44ch;
  margin: 9px auto 18px;
  font-size: 14.5px;
  line-height: 1.6;
  color: $a-ink-3;
}

.gaw-pager {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 26px;
}

.gaw-pager__nums {
  display: flex;
  align-items: center;
  gap: 2px;
}

.gaw-pager__step,
.gaw-pager__num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: $a-ink-2;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gaw-pager__step {
  border-color: $a-line;
  background: $a-white;
}

.gaw-pager__step:hover:not(:disabled),
.gaw-pager__num:hover:not(:disabled) {
  background: $a-white;
  color: $a-navy;
}

.gaw-pager__step:disabled {
  color: rgba(10, 37, 64, 0.22);
  cursor: default;
}

.gaw-pager__num.is-on {
  background: $a-blue;
  border-color: $a-blue;
  color: $a-white;
  font-weight: 600;
}

.gaw-pager__num.is-gap {
  min-width: 20px;
  color: $a-ink-4;
  cursor: default;
  pointer-events: none;
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gawRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gawDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  .gaw-top   { animation: gawRise 0.6s $a-ease backwards; }
  .gaw-blank { animation: gawRise 0.6s $a-ease 0.08s backwards; }

  .gaw-tile { animation: gawRise 0.62s $a-ease backwards; }

  .gaw-tile--pending { animation-delay: 0.06s; }
  .gaw-tile--active  { animation-delay: 0.12s; }
  .gaw-tile--value   { animation-delay: 0.18s; }
  .gaw-tile--done    { animation-delay: 0.24s; }

  .gaw-tile__rule { animation: gawDrawX 0.7s $a-ease 0.3s backwards; }

  .gaw-filters { animation: gawRise 0.6s $a-ease 0.28s backwards; }

  /* replays on every tab change, because ng-repeat rebuilds its
     nodes and the keyframe starts again with them */
  .gaw-card { animation: gawRise 0.5s $a-ease backwards; }

  .gaw-card--n1  { animation-delay: 0.02s; }
  .gaw-card--n2  { animation-delay: 0.05s; }
  .gaw-card--n3  { animation-delay: 0.08s; }
  .gaw-card--n4  { animation-delay: 0.11s; }
  .gaw-card--n5  { animation-delay: 0.14s; }
  .gaw-card--n6  { animation-delay: 0.17s; }
  .gaw-card--n7  { animation-delay: 0.20s; }
  .gaw-card--n8  { animation-delay: 0.23s; }
  .gaw-card--n9  { animation-delay: 0.26s; }
  .gaw-card--n10 { animation-delay: 0.29s; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {

  .gaw { padding: 26px 24px 64px; }

  .gaw-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 900px) {

  .gaw { padding: 22px 16px 56px; }

  .gaw-top__right {
    width: 100%;
    order: 2;
  }

  .gaw-search { width: 100%; }

  .gaw-tiles { grid-template-columns: minmax(0, 1fr); }

  .gaw-tabs {
    flex-wrap: nowrap;
    width: 100%;
    overflow-x: auto;
    padding-bottom: 3px;
    -webkit-overflow-scrolling: touch;
  }

  .gaw-tab { flex-shrink: 0; }

  /* the amount moves under the heading rather than being
     squeezed into a column too narrow to hold it */
  .gaw-card__head {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }

  .gaw-card__figure {
    text-align: left;
    padding-top: 14px;
    border-top: 1px solid $a-line-2;
  }

  .gaw-card__foot {
    align-items: flex-start;
    flex-direction: column;
  }

  .gaw-acts { width: 100%; }

  .gaw-btn { flex: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .gaw * { transition: none; }
  .gaw-tile:hover { transform: none; }
}

sp_widget.script:
(function () {

  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var AWARD     = 'x_enno_gatenow_grant_awards';
  var PROJECT   = 'x_enno_gatenow_project';

  var AWARD_STATES = 'pending,acknowledged,rejected';

  var me = gs.getUserID();

  data.success = false;
  data.error   = '';

  if (typeof input === 'undefined' || input === null) input = {};

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function param(key, dflt) {
    try {
      if (input && input[key] !== undefined && input[key] !== null) return input[key];
    } catch (e) { /* fall through */ }
    return dflt;
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  function daysSince(value) {
    var g = toGDT(value);
    if (!g) return null;
    try {
      var ms = GlideDateTime.subtract(g, new GlideDateTime()).getNumericValue();
      return Math.round(ms / 86400000);
    } catch (e) { return null; }
  }

  function num(raw) {
    if (raw === null || raw === undefined || raw === '') return 0;
    var s = '' + raw;
    if (s.indexOf(';') !== -1) s = s.split(';').pop();
    var n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }

  function commas(n) {
    var s = '' + Math.round(n);
    var out = '';
    var c = 0;
    for (var i = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out;
      c++;
      if (c % 3 === 0 && i > 0) out = ',' + out;
    }
    return out;
  }

  function fmtFull(n)  { return n > 0 ? '$' + commas(n) : ''; }

  function fmtShort(n) {
    if (!n) return '$0';
    if (n >= 1000000) return '$' + (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000)    return '$' + Math.round(n / 1000) + 'K';
    return '$' + commas(n);
  }

  /* ============================================================
     WRITE ACTIONS
     ============================================================ */

  var action = String(param('action', ''));

  function moveTo(sysId, fromState, toState, failMsg) {
    if (!sysId) { data.error = gs.getMessage('Nothing to update.'); return; }

    var gr = new GlideRecordSecure(AWARD);
    if (!gr.get(sysId)) {
      data.error = gs.getMessage('That award could not be found.');
      return;
    }

    var appGr = new GlideRecordSecure(APPLICANT);
    if (!appGr.get(gr.getValue('applicant')) || appGr.getValue('user') !== me) {
      data.error = gs.getMessage('That award does not belong to you.');
      return;
    }

    if (lower(gr.getValue('applicant_response')) !== fromState) {
      data.error = failMsg;
      return;
    }

    gr.setValue('applicant_response', toState);

    if (gr.update()) {
      data.success = true;
    } else {
      data.error = gs.getMessage('The update did not save. Try again.');
    }
  }

  if (action === 'acknowledge') {
    moveTo(String(param('sys_id', '')), 'pending', 'acknowledged', gs.getMessage('This award is no longer waiting on you. Refresh to see where it stands.'));
  }

  if (action === 'decline') {
    moveTo(String(param('sys_id', '')), 'pending', 'rejected', gs.getMessage('This award is no longer waiting on you. Refresh to see where it stands.'));
  }

  /* ============================================================
     CHROME
     ============================================================ */

  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'sidebar'));

  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (u.getDisplayName() || 'U').substring(0, 2).toUpperCase();

  data.pages = {
    programs: opt('programs_page', 'x_enno_gatenow_programs'),
    project : opt('project_page', 'x_enno_gatenow_project_detail'),
    detail  : opt('application_page', 'my_award_detail')
  };

  /* ============================================================
     AWARDS
     ============================================================ */

  data.awards = [];

  var counts  = { all: 0, pending: 0, active: 0, done: 0, declined: 0 };
  var totalValue = 0;
  var pendingValue = 0;
  var oldestPending = null;

  var STATE_MAP = {
    pending: {
      key   : 'pending',
      label : gs.getMessage('Waiting on you'),
      hint  : gs.getMessage('Accept or decline to move this forward')
    },
    acknowledged: {
      key   : 'active',
      label : gs.getMessage('Accepted'),
      hint  : gs.getMessage('The project opens once the program team sets it up')
    },
    rejected: {
      key   : 'declined',
      label : gs.getMessage('Declined'),
      hint  : gs.getMessage('You turned this award down')
    }
  };

  try {
    var applicantIds = [];
    var applicantGr = new GlideRecordSecure(APPLICANT);
    applicantGr.addQuery('user', me);
    applicantGr.query();

    while (applicantGr.next()) {
      applicantIds.push(applicantGr.getUniqueValue());
    }

    if (applicantIds.length > 0) {
      var gr = new GlideRecordSecure(AWARD);
      gr.addQuery('applicant', 'IN', applicantIds.join(','));
      gr.addQuery('applicant_response', 'IN', AWARD_STATES);
      gr.orderByDesc('sys_created_on');
      gr.query();

      while (gr.next()) {
        var stateVal = lower(gr.getValue('applicant_response'));
        var meta = STATE_MAP[stateVal];
        if (!meta) continue;

        var value = num(gr.getValue('build_grant_amount'));
        var waiting = (stateVal === 'pending') ? daysSince(gr.getValue('sys_created_on')) : null;

        var projectId = '';
        var projectName = '';

        if (stateVal === 'acknowledged') {
          var pj = new GlideRecordSecure(PROJECT);
          pj.addQuery('x_enno_gatenow_applicant', gr.getValue('applicant'));
          pj.setLimit(1);
          pj.query();
          if (pj.next()) {
            projectId = pj.getUniqueValue();
            projectName = pj.getValue('project_name') || pj.getValue('number');
          }
        }

        data.awards.push({
          sysId      : gr.getUniqueValue(),
          number     : gr.getValue('number'),
          program    : gr.getDisplayValue('program_name'),
          category   : gr.getDisplayValue('grant_program'),
          title      : '',
          state      : meta.key,
          stateLabel : meta.label,
          stateHint  : meta.hint,
          rawState   : stateVal,
          value      : value,
          valueText  : fmtFull(value),
          valueIsFinal: true,
          submitted  : fmtDate(gr.getValue('award_start_date')),
          moved      : fmtDate(gr.getValue('sys_updated_on')),
          waitingDays: waiting,
          projectId  : projectId,
          projectName: projectName,
          canAct     : (stateVal === 'pending')
        });

        counts.all++;
        counts[meta.key]++;

        if (meta.key !== 'declined') totalValue += value;

        if (stateVal === 'pending') {
          pendingValue += value;
          if (waiting !== null && (oldestPending === null || waiting > oldestPending)) {
            oldestPending = waiting;
          }
        }
      }
    }
  } catch (e) {
    gs.error('[Awards] ' + e.message);
  }

  data.counts = counts;

  /* ---------- tiles ---------- */
  data.tiles = [
    {
      key  : 'pending',
      label: gs.getMessage('Waiting on you'),
      value: '' + counts.pending,
      note : counts.pending === 0
               ? gs.getMessage('nothing needs a decision')
               : (oldestPending !== null && oldestPending > 0
                    ? gs.getMessage('oldest has been waiting') + ' ' + oldestPending + ' ' + gs.getMessage('days')
                    : gs.getMessage('awaiting your decision')),
      alert: counts.pending > 0
    },
    {
      key  : 'active',
      label: gs.getMessage('Active awards'),
      value: '' + counts.active,
      note : gs.getMessage('accepted or in delivery')
    },
    {
      key  : 'value',
      label: gs.getMessage('Total awarded'),
      value: fmtShort(totalValue),
      note : gs.getMessage('across every award except declined')
    },
    {
      key  : 'done',
      label: gs.getMessage('Completed'),
      value: '' + counts.done,
      note : gs.getMessage('delivered and closed')
    }
  ];

  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title      : opt('label_title', gs.getMessage('My awards')),
    search     : gs.getMessage('Search by program, reference or title'),
    tabAll     : gs.getMessage('All'),
    tabPending : gs.getMessage('Waiting on you'),
    tabActive  : gs.getMessage('Active'),
    tabDone    : gs.getMessage('Completed'),
    tabDeclined: gs.getMessage('Declined'),

    awarded    : gs.getMessage('Awarded'),
    requested  : gs.getMessage('Requested'),
    reference  : gs.getMessage('Reference'),
    submitted  : gs.getMessage('Submitted'),
    updated    : gs.getMessage('Last change'),
    project    : gs.getMessage('Project'),

    accept     : gs.getMessage('Accept award'),
    decline    : gs.getMessage('Decline'),
    viewProject: gs.getMessage('Open project'),
    viewApp    : gs.getMessage('View award'),

    waitingFor : gs.getMessage('Waiting'),
    days       : gs.getMessage('days'),
    day        : gs.getMessage('day'),

    emptyTitle : gs.getMessage('No awards yet'),
    emptyText  : gs.getMessage('Awards appear here once a funding panel has made a decision on one of your applications.'),
    emptyBtn   : gs.getMessage('Browse open programs'),
    noMatch    : gs.getMessage('Nothing matches this filter'),
    noMatchText: gs.getMessage('Try another tab, or clear the search.'),
    clear      : gs.getMessage('Clear'),

    acceptTitle: gs.getMessage('Accept this award?'),
    acceptText : gs.getMessage('Accepting starts the project and commits you to the reporting schedule attached to this program.'),
    acceptYes  : gs.getMessage('Yes, accept it'),
    declineTitle: gs.getMessage('Decline this award?'),
    declineText: gs.getMessage('This cannot be undone. The funding will be released to another applicant.'),
    declineYes : gs.getMessage('Yes, decline it'),
    keep       : gs.getMessage('Go back'),

    accepted   : gs.getMessage('Award accepted'),
    declined   : gs.getMessage('Award declined'),
    failed     : gs.getMessage('That did not work'),
    ok         : gs.getMessage('OK'),
    estimate   : gs.getMessage('Requested figure, the awarded amount is confirmed in your award letter')
  };

  data.pageSize = parseInt(opt('page_size', '10'), 10) || 10;

})();
